<script setup>
import { ref, reactive, computed, onMounted, onBeforeUnmount, shallowRef } from 'vue';
import { ArrowRight, ArrowUpRight, Plus, Flashlight, Map, BookOpen, Crosshair, Volume2, VolumeX, Settings2, X, Check, ChevronRight, Shield, Footprints, Wind, CircleHelp, Pause, RotateCcw, Radio, AlertTriangle, Coins, Power, Maximize, UserRound, DoorOpen, Clock, Eye, Target, HeartPulse, Headphones, Smartphone } from 'lucide-vue-next';
import { GameEngine } from './game/engine.js';
import { Mission, readSave, writeSave, purchase, UPGRADE_INFO } from './game/mission.js';
import { portrait } from './game/assets.js';
import TouchControls from './mobile/TouchControls.vue';
import {native,platform,touchDevice,initializeNative,nativeFeedback} from './mobile/platform.js';
import { App as NativeApp } from '@capacitor/app';
import './mobile/mobile.css';
import MapView from './MapView.vue';
const viewport = ref(null), screen = ref('menu'), overlay = ref(null), ready = ref(false), loading = ref(false), error = ref(null), locked = ref(false);
const isTouch=ref(touchDevice());let nativeCleanup=()=>{};
let engine, toastTimer, announcementTimer, effectTimer;
const save = reactive(readSave(localStorage));if(isTouch.value&&!localStorage.getItem('ktd-northline-v1'))save.settings.quality='balanced';
const hud = reactive({ state: 'investigate', location: 'Main atrium', floor: 0, x: 3, z: 30, yaw: Math.PI, timer: 0, stamina: 100, suspicion: 0, flashlight: false, blackout: 0, impairment: 0, aiming: false, ammo: 6, reserve: 30, prompt: null, clues: 0 });
const mission = shallowRef(null), result = ref(null), toast = ref(null), announcement = ref(null), clue = ref(null), badge = ref(null), mapFloor = ref(0), shotFlash = ref(false), transition = ref(false), hit = ref(false), soundCaption = ref(null);
const assignmentPortrait = ref(null);
const characterPortraits = reactive({ male: null, female: null });
const character = computed(() => save.character === 'male' ? 'Adrian' : 'Alex');
const countdown = computed(() => `${Math.floor(hud.timer/60).toString().padStart(2,'0')}:${Math.ceil(hud.timer%60).toString().padStart(2,'0')}`);
const duration = s => `${Math.floor(s/60)}:${Math.floor(s%60).toString().padStart(2,'0')}`;
const objectiveNumber = computed(() => hud.state === 'escape' ? '03' : hud.targetConfirmed ? '02' : '01');
const persist = () => writeSave(localStorage, save);
function notification(value) { toast.value = value; clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.value = null, 5500); }
function openOverlay(name) { overlay.value = name; engine?.pause(true); if (name === 'map') mapFloor.value = hud.floor; }
function closeOverlay() { overlay.value = null; clue.value = null; badge.value = null; if (screen.value === 'game') engine?.pause(false); }
function pause() { if (screen.value !== 'game' || loading.value) return; if (overlay.value) closeOverlay(); else openOverlay('pause'); }
async function startMission() {
  if (loading.value) return;
  engine?.audio.start();loading.value = true; error.value = null;
  try {
    persist(); mission.value = new Mission(save); result.value = null; overlay.value = null; toast.value = null; announcement.value = null; screen.value = 'game';
    await engine.start(mission.value, save.character); assignmentPortrait.value = engine.portrait(mission.value.target, mission.value.target.name.startsWith('Nurse') ? 'nurse' : 'doctor'); ready.value = true;
    notification({ text: isTouch.value?'Move with the stick, drag to look, and tap USE at the staff directory.':'Start at the staff directory. Press E to inspect it.', kind: 'info' });
  } catch (e) { error.value = `The game could not start: ${e.message}`; screen.value = 'menu'; }
  loading.value = false;
}
function toMenu() { engine?.stop(); screen.value = 'menu'; overlay.value = null; announcement.value = null; toast.value = null; persist(); }
function buy(id) { if (purchase(save, id)) { persist(); engine?.audio.sound('clue'); } }
function settingsChanged() { persist(); engine?.applySettings(save.settings); }
function toggleSound() { save.settings.volume = save.settings.volume ? 0 : .5; settingsChanged(); }
function fullscreen() { if(native)return; if (!document.fullscreenElement) document.documentElement.requestFullscreen?.().catch(()=>{}); else document.exitFullscreen?.(); }
function globalKey(e) {
  if (overlay.value === 'map' && (e.code === 'KeyM' || e.code === 'Tab')) { e.preventDefault(); closeOverlay(); }
  else if (overlay.value === 'journal' && e.code === 'KeyJ') closeOverlay();
  else if (screen.value !== 'game' && e.code === 'Escape' && overlay.value) closeOverlay();
}
onMounted(() => {
  try {
    engine = new GameEngine(viewport.value, save.settings, {
      ready: () => { ready.value = true; characterPortraits.male = engine.portrait({ gender:'male', skin:'#efddce', hair:'#514e50', accent:'#667683'}, 'civilian'); characterPortraits.female = engine.portrait({ gender:'female',skin:'#efddce',hair:'#433f3f',accent:'#697b88'}, 'civilian'); },
      hud: state => Object.assign(hud, state),
      pause, map: () => openOverlay('map'), journal: () => openOverlay('journal'), lock: value => locked.value = value,
      notify: notification,
      announcement: value => { announcement.value = value; clearTimeout(announcementTimer); announcementTimer = setTimeout(() => announcement.value = null, 11000); },
      soundCaption: text => { soundCaption.value=text; setTimeout(()=>soundCaption.value=null,6500); },
      clue: value => { nativeFeedback(); clue.value = value; openOverlay('clue'); },
      badge: value => { badge.value = value; openOverlay('badge'); },
      shot: () => { nativeFeedback('shot');shotFlash.value = true; setTimeout(() => shotFlash.value = false, 95); },
      hit: () => { hit.value = true; setTimeout(() => hit.value = false, 260); },
      transition: () => { transition.value = true; setTimeout(() => transition.value = false, 450); },
      result: value => { nativeFeedback(value.success?'success':'warning');result.value = value; screen.value = 'results'; overlay.value = null; persist(); },
    });
    // Dev-only inspection enables browser acceptance tests without changing the shipped UI.
    if (import.meta.env.DEV || import.meta.env.MODE==='native-test') window.__ktd = { get engine() { return engine; }, get mission() { return mission.value; }, get save() { return save; }, get hud() { return hud; } };
  } catch (e) { error.value = `WebGL could not initialize. Try a browser with hardware acceleration enabled. ${e.message}`; }
  initializeNative({background:()=>{persist();engine?.resetTouch();if(screen.value==='game'&&!overlay.value)openOverlay('pause');else engine?.pause(true);},back:()=>{if(overlay.value)closeOverlay();else if(screen.value==='game')pause();else if(screen.value==='results')toMenu();else NativeApp.exitApp();}}).then(cleanup=>nativeCleanup=cleanup);
  Object.defineProperty(window,'__northline',{configurable:true,get:()=>({platform,native,touch:isTouch.value,screen:screen.value,overlay:overlay.value,ready:ready.value,loading:loading.value,error:error.value,position:engine?.playerPos?.toArray(),yaw:engine?.yaw,paused:engine?.paused,frame:engine?.renderer.info.render.frame,fps:engine?.performance.fps,state:engine?.mission?.state,ammo:engine?.ammo,flashlight:engine?.flashlight,clues:engine?.mission?.clues.length,controls:{...engine?.touchInput},inputEvents:{...engine?.inputEvents},coins:save.coins,upgrades:{...save.upgrades},settings:{...save.settings},audio:{state:engine?.audio.ctx?.state,samples:Object.keys(engine?.audio.samples||{}),voices:engine?.audio.dialogueBuffers.size},url:location.href})});
  window.addEventListener('keydown', globalKey);
});
onBeforeUnmount(() => { nativeCleanup();engine?.dispose(); clearTimeout(toastTimer); clearTimeout(announcementTimer); clearTimeout(effectTimer); window.removeEventListener('keydown', globalKey); });
</script>
<template>
  <main class="game-shell" :style="{ '--impairment-blur': `${(hud.impairmentStrength || 0)*3}px` }" :class="[{ 'mobile-mode':isTouch,'native-mode':native, 'in-game': screen === 'game', 'impaired': hud.impairment > 0 && screen === 'game', 'blackout': hud.blackout > 0 && screen === 'game', 'emergency': hud.state === 'escape' && screen === 'game' }, screen]">
    <div v-if="isTouch" class="rotate-phone"><Smartphone :size="44"/><h2>Turn your phone.</h2><p>Northline plays in landscape. Rotate your phone for the full game and touch controls.</p></div>
    <div ref="viewport" class="viewport" :class="{ 'shot': shotFlash }"></div>
    <div class="vignette" aria-hidden="true"></div><div class="grain" aria-hidden="true"></div>
    <div v-if="transition" class="floor-transition"></div>
    <template v-if="screen === 'menu'">
      <header class="menu-header"><a class="brand" href="#" @click.prevent="toMenu"><span class="brand-mark"><Plus :size="25" :stroke-width="1.3"/></span><span>NORTHLINE<small>MEDICAL CENTER</small></span></a><div class="header-status"><span class="live-dot"></span> ALL SYSTEMS OPERATIONAL <span class="header-time">02:14 AM</span></div></header>
      <section class="menu-content">
        <div class="eyebrow"><span class="line"></span> A THIRD-PERSON STEALTH THRILLER</div>
        <h1>KILL THE<br/><span>DOCTOR.</span></h1>
        <p class="tagline">Everyone has a reason to be here.<br/>Yours is different.</p>
        <div class="mission-premise"><span class="section-number">01 /</span><p>Enter Northline. Follow the evidence. Find your assigned target. Then get out before the hospital locks down.</p></div>
        <div class="character-select"><div class="field-label">SELECT YOUR PROTAGONIST <span>Equal abilities</span></div>
          <div class="character-options"><button :class="{selected: save.character === 'male'}" @click="save.character = 'male'; persist()" :aria-pressed="save.character === 'male'"><img v-if="characterPortraits.male" :src="characterPortraits.male" alt="Adrian portrait"/><UserRound v-else :size="24"/><span>ADRIAN<small>Male protagonist</small></span><Check v-if="save.character==='male'" :size="17"/></button><button :class="{selected: save.character === 'female'}" @click="save.character = 'female'; persist()" :aria-pressed="save.character === 'female'"><img v-if="characterPortraits.female" :src="characterPortraits.female" alt="Alex portrait"/><UserRound v-else :size="24"/><span>ALEX<small>Female protagonist</small></span><Check v-if="save.character==='female'" :size="17"/></button></div>
        </div>
        <button class="primary start-button" @click="startMission" :disabled="loading || !!error"><span>{{ loading ? 'PREPARING ASSIGNMENT' : 'ENTER THE HOSPITAL' }}<small>MISSION {{ String(save.completed + 1).padStart(2, '0') }} / {{ save.settings.difficulty.toUpperCase() }}</small></span><ArrowRight :size="24"/></button>
        <div class="menu-links"><button @click="openOverlay('equipment')"><Crosshair :size="15"/> Equipment <span v-if="save.coins">{{ save.coins }}</span></button><button @click="openOverlay('controls')"><CircleHelp :size="15"/> How to play</button><button @click="openOverlay('settings')"><Settings2 :size="15"/> Settings</button></div>
        <p v-if="error" class="error-message">{{ error }}</p>
      </section>
      <aside class="scene-label"><span class="eyebrow">NORTHLINE / MAIN BUILDING</span><span class="scene-title">The night shift.</span><p>Two floors. Sixteen departments.<br/>One way out.</p><div class="scene-meta"><span>THREE CONNECTED WINGS</span><span>G + 1</span></div></aside>
      <footer class="menu-footer"><span><Headphones :size="13"/> HEADPHONES RECOMMENDED</span><span class="menu-version">{{ ready ? 'READY TO ENTER' : 'LOADING CHARACTER ASSETS' }} <span class="live-dot" :class="{loading: !ready}"></span></span><button @click="openOverlay('credits')">BUILD 01.2 <ArrowUpRight :size="12"/></button></footer>
    </template>
    <template v-if="screen === 'game'">
      <header class="hud-top"><section class="mission-hud"><div class="eyebrow"><span class="live-dot" :class="{alert: hud.state==='escape'}"></span> {{ hud.state === 'escape' ? 'EMERGENCY / ESCAPE' : 'NORTHLINE / INFILTRATION' }}</div><div class="objective-row"><span class="objective-number">{{ objectiveNumber }}</span><div><span class="objective">{{ hud.objective }}</span><small>{{ hud.location }} <span> / </span> {{ hud.floor ? 'FIRST FLOOR' : 'GROUND FLOOR' }}</small></div></div><div class="evidence-progress"><i v-for="n in 3" :key="n" :class="{active: n <= hud.clues}"></i><span>{{ hud.clues }}/3 EVIDENCE FOUND</span></div></section>
        <section class="target-hud"><div class="target-text"><span class="eyebrow">{{ hud.targetConfirmed ? 'IDENTITY CONFIRMED' : 'YOUR ASSIGNMENT' }}</span><strong>{{ mission?.target.name }}</strong><small>{{ hud.clues ? `${mission?.target.room.name} · ${mission?.target.floor ? 'Floor 1' : 'Ground floor'}` : 'Department unknown' }}</small></div><div class="target-portrait" :class="{confirmed: hud.targetConfirmed}"><img :src="assignmentPortrait" alt="Assigned target portrait"/><span v-if="hud.state==='escape'"><Check :size="22"/></span><span v-else class="portrait-marker"><Target :size="14"/></span></div></section>
      </header>
      <div v-if="hud.state === 'escape'" class="countdown" :class="{urgent: hud.timer < 30}"><Radio :size="15"/><span>POLICE RESPONSE</span><strong>{{ countdown }}</strong><small>Reach the main entrance · ground floor</small></div>
      <div class="reticle" :class="{aiming: hud.aiming, hit}"><span></span><i></i><b></b></div>
      <div v-if="toast && !overlay" class="toast" :class="toast.kind"><span class="toast-line"></span><span>{{ toast.text }}</span></div>
      <div v-if="hud.prompt && !overlay" class="interaction-prompt"><kbd>E</kbd><span>{{ hud.prompt.text }}</span></div>
      <div v-if="hud.impairment > 0" class="status-effect"><Wind :size="15"/> CONTAMINATION <span>RECOVERY {{Math.ceil(hud.impairment)}}s</span></div>
      <div v-if="hud.blackout > 0" class="power-status"><Power :size="13"/> EMERGENCY POWER <small>{{ Math.ceil(hud.blackout) }}s</small></div>
      <div v-if="!overlay" class="npc-dialogues"><div v-for="(line,i) in hud.dialogues" :key="i" class="npc-dialogue" :style="{left: `${line.x}%`, top: `${line.y}%`}"><span>{{line.speaker}}</span><p>{{line.text}}</p></div></div>
      <div v-if="soundCaption && !overlay" class="ambient-caption">{{soundCaption}}</div>
      <div v-if="announcement && !overlay" class="announcement"><span><Radio :size="14"/> {{ announcement.label }}</span><p>“{{ announcement.text }}”</p></div>
      <footer class="hud-bottom"><section class="player-status"><div class="operative-name"><span class="status-bar"></span>{{ character.toUpperCase() }}<span class="eyebrow">{{ hud.crouched ? 'CROUCHED' : hud.suspicion > 70 ? 'EXPOSED' : hud.suspicion > 30 ? 'SUSPICIOUS' : 'UNNOTICED' }}</span></div><div class="stamina-track"><i :style="{width: `${hud.stamina}%`}"></i></div><div class="hud-tools"><button @click="engine.toggleFlash()" :class="{active: hud.flashlight}" title="Toggle flashlight (F)"><Flashlight :size="16"/><kbd>F</kbd></button><button @click="openOverlay('journal')" title="Evidence journal (J)"><BookOpen :size="16"/><kbd>J</kbd></button><button @click="pause" title="Pause game (Escape)"><Pause :size="15"/><kbd>ESC</kbd></button><button @click="toggleSound" title="Toggle sound"><Volume2 v-if="save.settings.volume" :size="16"/><VolumeX v-else :size="16"/></button></div></section>
        <section class="weapon-status"><span class="weapon-label">{{ hud.reloading ? 'RELOADING' : 'SERVICE PISTOL' }}</span><div><strong>{{ String(hud.ammo).padStart(2,'0') }}</strong><span>/ {{ String(hud.reserve).padStart(2,'0') }}</span><button @click="engine.reload()" title="Reload (R)"><RotateCcw :size="14"/><kbd>R</kbd></button></div><small>{{ isTouch ? 'Tap AIM, then FIRE' : 'Hold right mouse to aim · left mouse to fire' }}</small></section>
        <button class="minimap" @click="openOverlay('map')" aria-label="Open hospital map"><MapView :floor="hud.floor" :hud="hud" :target="mission?.target" :clues="hud.clues" mini/><span><Map :size="13"/> {{ hud.floor ? 'FLOOR 1' : 'GROUND FLOOR' }} <kbd>M</kbd></span></button>
      </footer>
      <div v-if="!isTouch && !locked && !overlay" class="mouse-hint">Click the scene for mouse look <span>·</span> arrow keys also turn</div>
      <TouchControls v-if="isTouch && !overlay && !loading" :engine="engine" :hud="hud" @map="openOverlay('map')" @journal="openOverlay('journal')" @pause="pause"/>
    </template>
    <section v-if="screen==='results' && result" class="results-screen"><div class="results-panel"><div class="eyebrow"><span class="line"></span> ASSIGNMENT {{ String(mission?.round).padStart(2,'0') }} / DEBRIEF</div><h2>{{ result.success ? 'OUT OF' : 'END OF' }}<br/><span>{{ result.success ? 'THE BUILDING.' : 'THE LINE.' }}</span></h2><p class="result-reason">{{ result.reason }}</p><div class="result-checks"><span :class="{yes: result.targetDown}"><Check v-if="result.targetDown" :size="15"/><X v-else :size="15"/> TARGET {{ result.targetDown ? 'ELIMINATED' : 'ACTIVE' }}</span><span :class="{yes: result.escaped}"><DoorOpen :size="15"/> {{ result.escaped ? 'ESCAPED' : 'INTERCEPTED' }}</span><span><Clock :size="15"/> {{ duration(result.duration) }}</span></div><div class="reward-card"><div><span class="eyebrow">MISSION REWARD</span><strong><Coins :size="25"/> {{ result.coins }}<small>COINS</small></strong></div><span class="balance">BALANCE <b>{{ save.coins }}</b></span></div><div v-if="result.breakdown.length" class="reward-breakdown"><div v-for="row in result.breakdown" :key="row.label"><span>{{ row.label }}</span><b>+{{ row.coins }}</b></div></div><p v-else class="failure-reward">Rewards are earned only after a successful escape.</p><button class="primary" @click="startMission"><span>{{ result.success ? 'NEXT ASSIGNMENT' : 'RETRY ASSIGNMENT' }}</span><ArrowRight :size="22"/></button><div class="result-actions"><button @click="openOverlay('equipment')"><Crosshair :size="16"/> Upgrade equipment</button><button @click="toMenu">Return to menu</button></div></div></section>
    <div v-if="loading" class="loading-screen"><div class="loader-mark"><Plus :size="42"/></div><span class="eyebrow">NORTHLINE MEDICAL CENTER</span><h3>Preparing your assignment.</h3><p>Loading the hospital and character assets…</p></div>
    <div v-if="overlay" class="modal-backdrop" @click.self="closeOverlay">
      <section class="modal" :class="{wide: ['map','equipment','controls'].includes(overlay)}" role="dialog" aria-modal="true" :aria-label="overlay">
        <header class="modal-header"><span class="eyebrow">NORTHLINE / {{ overlay === 'clue' ? 'EVIDENCE' : overlay.toUpperCase() }}</span><button class="icon-button" @click="closeOverlay" aria-label="Close dialog"><X :size="20"/></button></header>
        <template v-if="overlay==='pause'"><h2>Take a breath.</h2><p class="modal-lead">The hospital can wait. Your mission is paused.</p><div class="pause-actions"><button class="primary" @click="closeOverlay"><span>RESUME MISSION</span><ArrowRight :size="20"/></button><button class="secondary" @click="overlay='controls'">Controls & field guide</button><button class="secondary" @click="overlay='settings'">Settings</button><button class="text-button" @click="overlay='leave'">Abandon assignment</button></div></template>
        <template v-if="overlay==='leave'"><h2>Leave the assignment?</h2><p class="modal-lead">This mission will be recorded as unsuccessful. Your earned coins and upgrades stay saved.</p><button class="primary" @click="mission.finish(false, 'Assignment abandoned.'); persist(); toMenu()">ABANDON MISSION</button><button class="secondary" @click="closeOverlay">Keep playing</button></template>
        <template v-if="overlay==='map'"><div class="modal-title-row"><h2>Know your way out.</h2><div class="floor-tabs"><button :class="{selected: mapFloor===0}" @click="mapFloor=0">G</button><button :class="{selected: mapFloor===1}" @click="mapFloor=1">1</button></div></div><div class="map-layout"><MapView :floor="mapFloor" :hud="hud" :target="mission?.target" :clues="hud.clues"/><aside class="map-notes"><span class="eyebrow">{{ mapFloor ? 'FIRST FLOOR' : 'GROUND FLOOR' }}</span><h3>{{ mapFloor ? 'Specialist care' : 'Clinical & diagnostics' }}</h3><div class="map-legend"><span><i class="blue-dot"></i> Your position</span><span><i class="gold-dot"></i> Evidence terminals</span><span><i class="outline-dot"></i> Known departments</span></div><p>Doors connect the concourse and outer passages. Use either route to move between wings.</p><p>The lift at the north end connects both floors. The main entrance is on the ground floor.</p><div v-if="hud.clues" class="known-location"><span class="eyebrow">CONFIRMED ASSIGNMENT</span><strong>{{ mission?.target.room.name }}</strong><small>{{ mission?.target.room.wing }} wing · {{ mission?.target.floor ? 'Floor 1' : 'Ground floor' }}</small></div><button class="secondary" @click="closeOverlay">RETURN TO MISSION <kbd>M</kbd></button></aside></div></template>
        <template v-if="overlay==='journal'"><h2>Follow the evidence.</h2><p class="modal-lead">{{ mission?.target.name }} / {{ hud.clues }} of 3 records found</p><div v-if="mission?.clues.length" class="journal"><article v-for="(item,i) in mission.clues" :key="item.type"><span class="section-number">0{{i+1}}</span><div><span class="eyebrow">{{item.source}}</span><h3>{{item.title}}</h3><p>{{item.text}}</p><small>RECORDED {{duration(item.time)}}</small></div></article></div><div v-else class="empty-journal"><BookOpen :size="32"/><p>No evidence yet. Inspect the staff directory in the entrance atrium, staff schedules in the east concourse, or the handover logs outside the clinical wings.</p></div><button class="secondary" @click="closeOverlay">CONTINUE INVESTIGATION <kbd>J</kbd></button></template>
        <template v-if="overlay==='clue' && clue"><div class="clue-icon"><BookOpen :size="27"/></div><h2>{{clue.title}}.</h2><span class="eyebrow">{{clue.source}}</span><p class="clue-text">{{clue.text}}</p><div class="record-state"><Check :size="15"/> ADDED TO EVIDENCE JOURNAL</div><button class="primary" @click="closeOverlay"><span>RECORD & CONTINUE</span><ArrowRight :size="20"/></button></template>
        <template v-if="overlay==='badge' && badge"><div class="clue-icon"><UserRound :size="27"/></div><span class="eyebrow">STAFF IDENTITY / VERIFIED</span><h2>{{badge.name}}</h2><p class="modal-lead">{{badge.role}}</p><div class="badge-match" :class="{matched: badge.target}"><Target :size="18"/> {{ badge.target ? 'MATCHES YOUR ASSIGNMENT' : 'DOES NOT MATCH YOUR ASSIGNMENT' }}</div><p>{{badge.target ? 'Identity confirmed. Complete the objective, then reach the main entrance before police respond.' : 'Continue your investigation. Verify the name on the badge before you act.'}}</p><button class="primary" @click="closeOverlay">CONTINUE <ArrowRight :size="20"/></button></template>
        <template v-if="overlay==='equipment'"><div class="modal-title-row"><div><h2>Travel light.</h2><p class="modal-lead">Equipment upgrades persist across assignments.</p></div><div class="equipment-balance"><Coins :size="18"/> {{save.coins}}</div></div><div class="loadout"><Crosshair :size="22"/><div><strong>Service pistol</strong><span>6-round magazine · 30 reserve · available from the start</span></div><small>EQUIPPED</small></div><div class="upgrade-grid"><article v-for="(u,i) in UPGRADE_INFO" :key="u.id"><component :is="[Footprints,Flashlight,Wind,Crosshair][i]" :size="25"/><span class="eyebrow">LEVEL {{save.upgrades[u.id]}} / {{u.max}}</span><h3>{{u.name}}</h3><p>{{u.description}}</p><button @click="buy(u.id)" :disabled="save.upgrades[u.id]>=u.max || save.coins<u.cost*(save.upgrades[u.id]+1)"><template v-if="save.upgrades[u.id]>=u.max"><Check :size="15"/> FULLY UPGRADED</template><template v-else>UPGRADE <span><Coins :size="14"/> {{u.cost*(save.upgrades[u.id]+1)}}</span></template></button></article></div><p class="equipment-tip">Complete the assignment and escape to earn coins. Evidence and efficient escapes earn additional rewards.</p></template>
        <template v-if="overlay==='settings'"><h2>Make yourself comfortable.</h2><div class="settings-list"><label><span>Sound volume<small>Music, atmosphere & effects</small></span><input type="range" min="0" max="1" step=".05" v-model.number="save.settings.volume" @input="settingsChanged"/></label><label><span>Spoken dialogue & announcements<small>Captions are always shown</small></span><input type="checkbox" v-model="save.settings.speech" @change="settingsChanged"/></label><label><span>{{isTouch?'Camera sensitivity':'Mouse sensitivity'}}</span><input type="range" min=".3" max="2" step=".1" v-model.number="save.settings.sensitivity" @input="settingsChanged"/></label><label><span>Visual quality<small>Balanced helps slower devices</small></span><select v-model="save.settings.quality" @change="settingsChanged"><option value="high">High</option><option value="balanced">Balanced</option><option value="low">Low</option></select></label><label><span>Mission difficulty<small>Applies to your next assignment</small></span><select v-model="save.settings.difficulty" @change="settingsChanged"><option value="relaxed">Relaxed · 150s escape</option><option value="standard">Standard · 110s escape</option><option value="hard">Hard · 75s escape</option></select></label></div><button v-if="!native" class="secondary" @click="fullscreen"><Maximize :size="16"/> Toggle fullscreen</button><p class="settings-note">Your settings, coins, and equipment save automatically in this browser.</p></template>
        <template v-if="overlay==='controls'"><h2>Your night-shift field guide.</h2><div class="controls-layout"><section v-if="isTouch" class="controls-list"><div><span>Move / strafe</span><b>Left thumbstick</b></div><div><span>Look around</span><b>Drag right side</b></div><div><span>Sprint / crouch</span><b>RUN / CROUCH</b></div><div><span>Doors, badges, clues, lift</span><b>USE</b></div><div><span>Flashlight</span><b>LIGHT</b></div><div><span>Aim / shoot</span><b>AIM / FIRE</b></div><div><span>Adjust aim while firing</span><b>Drag FIRE</b></div><div><span>Reload</span><b>RELOAD</b></div><div><span>Map / journal / pause</span><b>Top-right icons</b></div></section><section v-else class="controls-list"><div><span>Move / strafe</span><b><kbd>W</kbd><kbd>A</kbd><kbd>S</kbd><kbd>D</kbd></b></div><div><span>Look around</span><b>Mouse / <kbd>←</kbd><kbd>→</kbd></b></div><div><span>Run / crouch</span><b><kbd>SHIFT</kbd><kbd>C</kbd></b></div><div><span>Read / inspect / use door</span><kbd>E</kbd></div><div><span>Flashlight</span><kbd>F</kbd></div><div><span>Aim / fire</span><b>Right / left mouse</b></div><div><span>Keyboard aim / fire</span><b><kbd>V</kbd><kbd>SPACE</kbd></b></div><div><span>Reload</span><kbd>R</kbd></div><div><span>Map / evidence / pause</span><b><kbd>M</kbd><kbd>J</kbd><kbd>ESC</kbd></b></div></section><section class="field-guide"><article><span>01</span><div><h3>Investigate.</h3><p>Read the directory in the atrium. Schedules and handover logs reveal the department and room. Use the map to plan your route.</p></div></article><article><span>02</span><div><h3>Confirm the badge.</h3><p>Approach staff and press E. Match your assigned target before aiming. Patients are protected: harming one fails the mission.</p></div></article><article><span>03</span><div><h3>Find your exit.</h3><p>Eliminating the target starts the police countdown. Return to the ground-floor main entrance. Evade security and keep your flashlight ready.</p></div></article></section></div><p class="controls-note">{{isTouch?'Use the movement stick and drag the right side to look. USE interacts, AIM steadies your weapon, and FIRE shoots. Maps and menus pause the mission.':'Click the scene to capture the mouse. Escape releases it. Maps and menus pause the mission.'}}</p><button class="primary" @click="closeOverlay">UNDERSTOOD <Check :size="18"/></button></template>
        <template v-if="overlay==='credits'"><h2>Northline after hours.</h2><p class="modal-lead">Kill the Doctor · Playable browser edition</p><p>Built with Vue 3, Three.js, and Web Audio. Original modular hospital, procedural medical equipment, dynamic lighting, character rigs, and persistent mission progression.</p><p>Avatar assets from Ready Player Me / Wolf3D through the three.ws sample collection. Animation clips from Adobe Mixamo.</p><p>All people, events, and medical effects in this game are fictional.</p><p><a href="/credits.txt" target="_blank" rel="noopener">Asset sources & license notices ↗</a></p><span class="eyebrow">LOCAL SAVE / NO ACCOUNT REQUIRED</span></template>
      </section>
    </div>
  </main>
</template>
